/* @lc app=leetcode id=2272 lang=kotlin */ class Solution { fun largestVariance(s: String): Int = ('a'..'z').filter { it in s }.let { ls -> ls.flatMap { a -> ls.filter { it != a }.map { b -> s.fold(Triple(0, -1_000_000, 0)) { (m0, m1, best), c -> (if (c == a) Pair(m0 + 1, m1 + 1) else if (c == b) maxOf(m0, m1).let { v -> Pair(0, v - 1) } else Pair(m0, m1)).let { (n0, n1) -> Triple(n0, n1, maxOf(best, n1)) } }.third } }.maxOrNull() ?: 0 } }